h1, h2, h3, h4, h5 {
  color: #00ffe7 !important;
  text-shadow: 0 0 5px #00ffe7;
}

/* Ссылки */
a {
  color: #00bfff !important;
  text-decoration: none;
}

a:hover {
  color: #00ffe7 !important;
  text-shadow: 0 0 5px #00ffe7;
}

