style.css:
body {
  background: linear-gradient(to right, #1e3c72, #2a5298);
  color: white;
  font-family: 'Segoe UI', sans-serif;
  text-align: center;
  padding: 50px;
}

button {
  background-color: #ff6b6b;
  border: none;
  border-radius: 8px;
  color: white;
  padding: 12px 24px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #ff4b4b;
}
